// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime, uint256 depositAmount, uint256 collectAmount) public {
        // 1. Keep amounts in admissible range
        vm.assume(depositAmount >= 1 && depositAmount <= 1000 ether);
        vm.assume(collectAmount >= 1 && collectAmount <= depositAmount);
        // MinSum is 1 ether; ensure balance meets it for Collect
        vm.assume(collectAmount >= 1 ether);

        // 2. Deploy re-entrant attacker
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), depositAmount);

        // Warp to ensure unlockTime allows Collect
        vm.warp(1);

        // Attacker deposits via Put (which in the buggy version is missing nonReentrant_)
        vm.prank(address(attacker));
        c.Put{value: depositAmount}(unlockTime);

        // Record contract balance before Collect
        uint256 preCollectBalance = address(c).balance;

        // Wrap Collect call to handle potential re-entrant revert
        bool collectOk = true;
        try c.Collect(collectAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // 3. The invariant: contract balance after execution equals initial balance + total deposits - total successful withdrawals.
        // Here, if Collect succeeded, contract balance should be preCollectBalance - collectAmount (no extra deposit).
        // In the correct contract, nonReentrant prevents re-entrant Put during Collect, so balance stays consistent.
        // In the buggy version, re-entrant Put deposits extra Ether, inflating contract balance.
        if (collectOk) {
            uint256 postCollectBalance = address(c).balance;
            assertTrue(postCollectBalance == preCollectBalance - collectAmount);
        } else {
            // If Collect reverted, contract balance should remain unchanged
            assertTrue(address(c).balance == preCollectBalance);
        }
    }
}

contract ReentrantAttacker {
    C public target;
    bool private attacking;
    uint256 private deposited;

    constructor(C _target) {
        target = _target;
        attacking = false;
    }

    receive() external payable {
        if (!attacking && deposited > 0) {
            attacking = true;
            // Re-enter Put with same unlockTime (any value > block.timestamp works)
            target.Put(block.timestamp + 1000);
            attacking = false;
        }
    }

    function deposit(uint256 unlockTime) external payable {
        deposited = msg.value;
        target.Put{value: msg.value}(unlockTime);
    }
}

