pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(uint256 unlockTime1, uint256 unlockTime2, uint256 depositAmount, uint256 withdrawAmount) public {
        // constrain inputs to admissible domain: deposit at least withdraw, time in future
        depositAmount = bound(depositAmount, 1 ether, 1000 ether);
        unlockTime1 = bound(unlockTime1, block.timestamp + 1, block.timestamp + 365 days);
        unlockTime2 = bound(unlockTime2, block.timestamp + 1, block.timestamp + 365 days);
        withdrawAmount = bound(withdrawAmount, 1, depositAmount);

        // deploy adversarial reentrant collector that calls Put during Collect's external call
        ReentrantCollector attacker = new ReentrantCollector(address(c));
        address attackerAddr = address(attacker);

        // fund attacker
        vm.deal(attackerAddr, depositAmount);

        // attacker makes first Put with unlockTime1
        vm.prank(attackerAddr);
        c.Put{value: depositAmount}(unlockTime1);

        // warp past unlockTime1
        vm.warp(unlockTime1 + 1);

        // attacker calls Collect with withdrawAmount, and during the external call,
        // receives Ether which triggers re-entrant Put with unlockTime2
        uint256 preCollectUnlockTime = c.Acc(attackerAddr).unlockTime;
        vm.prank(attackerAddr);
        c.Collect(withdrawAmount);

        // after the sequence, if a withdrawal happened, the recorded unlockTime should not exceed the time when the withdrawal occurred
        // The reference contract (with nonReentrant_ on Put) ensures that the unlockTime remains preCollectUnlockTime during external call,
        // so after Collect, unlockTime is <= preCollectUnlockTime.
        // The buggy contract allows the reentrant Put to set unlockTime to unlockTime2 (future), which is > block.timestamp at withdrawal time.
        uint256 postCollectUnlockTime = c.Acc(attackerAddr).unlockTime;
        assertTrue(postCollectUnlockTime <= preCollectUnlockTime);
    }
}

contract ReentrantCollector {
    C public target;
    bool private locked;

    constructor(address _target) {
        target = C(payable(_target));
    }

    receive() external payable {
        if (!locked) {
            locked = true;
            // re-enter with a future unlockTime to violate the invariant
            target.Put(block.timestamp + 365 days);
        }
    }
}

