contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(uint256 unlockTime1, uint256 unlockTime2, uint256 amount1, uint256 amount2, address sender) public {
        vm.assume(sender != address(0) && sender != address(this) && sender != address(c));
        vm.assume(amount1 > 0 && amount2 > 0);
        vm.assume(unlockTime1 > block.timestamp && unlockTime2 < unlockTime1);
        vm.assume(unlockTime2 > block.timestamp);
        vm.assume(amount1 + amount2 >= c.MinSum());
        vm.assume(address(c).balance == 0);

        vm.deal(sender, amount1 + amount2);

        vm.startPrank(sender);
        c.Put{value: amount1}(unlockTime1);
        vm.stopPrank();

        uint recordedUnlockBefore = c.Acc(sender).unlockTime;

        vm.warp(block.timestamp + 1 days);

        vm.startPrank(sender);
        c.Put{value: amount2}(unlockTime2);
        vm.stopPrank();

        uint balanceAfter = c.Acc(sender).balance;
        uint unlockTimeAfter = c.Acc(sender).unlockTime;

        bool collectOk = false;
        if (balanceAfter >= c.MinSum() && block.timestamp > unlockTimeAfter) {
            vm.startPrank(sender);
            try c.Collect(balanceAfter) {
                collectOk = true;
            } catch {
                collectOk = false;
            }
            vm.stopPrank();
        } else {
            collectOk = true; // Not eligible, so vacuously holds
        }

        assertTrue(collectOk, "Collection should succeed if conditions met after second Put");
    }
